mapper.select:
SELECT mdhc.id, mdhc.create_time, mdhc.update_time, mdhc.bool_delete_enum, mdhc.version, mdhc.machine_part_type, mdhc.steel_classification_id, mdhc.statistics_mode, mdhc.process, mdhc.pricing_manner, mdhc.measurement_manner, mdhc.organization_inside_price, mdhc.organization_outside_price, mdhc.fixed_price, mdhc.statistics_config_statistics_mode, ssc.name AS steel_classification_name, sscm.keyword AS specification_prefix_type, mbp.id AS process_id, mbp.name AS process_name FROM mes_drill_hole_config mdhc LEFT JOIN sys_steel_classification ssc ON ssc.id = mdhc.steel_classification_id LEFT JOIN sys_steel_classification_match sscm ON sscm.bool_delete_enum = FALSE AND sscm.steel_id = mdhc.steel_classification_id LEFT JOIN mes_building_process mbp ON FIND_IN_SET(mbp.id, mdhc.process) > 0
mdhc.bool_delete_enum = FALSE
AND mdhc.statistics_config_statistics_mode = #{statisticsConfigStatisticsMode}

SELECT mdhc.id, mdhc.create_time, mdhc.update_time, mdhc.bool_delete_enum, mdhc.version, mdhc.machine_part_type, mdhc.steel_classification_id, mdhc.statistics_mode, mdhc.process, mdhc.pricing_manner, mdhc.measurement_manner, mdhc.organization_inside_price, mdhc.organization_outside_price, mdhc.fixed_price, mdhc.statistics_config_statistics_mode, ssc.name AS steel_classification_name, sscm.keyword AS specification_prefix_type, mbp.id AS process_id, mbp.name AS process_name FROM mes_drill_hole_config mdhc LEFT JOIN sys_steel_classification ssc ON ssc.id = mdhc.steel_classification_id LEFT JOIN sys_steel_classification_match sscm ON sscm.bool_delete_enum = FALSE AND sscm.steel_id = mdhc.steel_classification_id LEFT JOIN mes_building_process mbp ON FIND_IN_SET(mbp.id, mdhc.process) > 0
mdhc.bool_delete_enum = FALSE
AND mdhc.id in (
#{i}
)
